    58              <AttachmentContext.Provider value={getAttachmentValue(item)}>
    59                  <MenuItemWithTopDescription
    60                      key={item.title}
    61                      description={item.title}
    62                      title={item.note}
    63                      onPress={item.action}
    64                      shouldShowRightIcon={!item.disabled}
    65                      numberOfLinesTitle={0}
    66                      shouldRenderAsHTML
    67                      brickRoadIndicator={item.brickRoadIndicator}
    68                      disabled={item.disabled}
    69                      shouldGreyOutWhenDisabled={false}
