    42  function PrivateNotesEditPage({route, report, accountID}: PrivateNotesEditPageProps) {
    43      const backTo = route.params.backTo;
    44      const styles = useThemeStyles();
    45      const {translate} = useLocalize();
    46      const [personalDetailsList] = useOnyx(ONYXKEYS.PERSONAL_DETAILS_LIST);
    47
    48      // We need to edit the note in markdown format, but display it in HTML format
    49      const [privateNote, setPrivateNote] = useState(
    50          () => ReportActions.getDraftPrivateNote(report.reportID).trim() || Parser.htmlToMarkdown(report?.privateNotes?.[Number(route.params.accountID)]?.note ?? '').trim(),
    51      );
    52
    53      /**
    54       * Save the draft of the private note. This debounced so that we're not ceaselessly saving your edit. Saving the draft
    55       * allows one to navigate somewhere else and come back to the private note and still have it in edit mode.
    56       */
    57      const debouncedSavePrivateNote = useMemo(
    58          () =>
    59              lodashDebounce((text: string) => {
    60                  ReportActions.savePrivateNotesDraft(report.reportID, text);
    61              }, 1000),
    62          [report.reportID],
    63      );
    64
    65      // To focus on the input field when the page loads
    66      const privateNotesInput = useRef<AnimatedTextInputRef | null>(null);
    67      const focusTimeoutRef = useRef<NodeJS.Timeout | null>(null);
    68
    69      useHtmlPaste(privateNotesInput);
    70
    71      useFocusEffect(
    72          useCallback(() => {
    73              focusTimeoutRef.current = setTimeout(() => {
    74                  if (privateNotesInput.current) {
    75                      privateNotesInput.current.focus();
    76                  }
    77                  return () => {
    78                      if (!focusTimeoutRef.current) {
    79                          return;
    80                      }
    81                      clearTimeout(focusTimeoutRef.current);
    82                  };
    83              }, CONST.ANIMATED_TRANSITION);
    84          }, []),
    85      );
    86
    87      const savePrivateNote = () => {
    88          const originalNote = report?.privateNotes?.[Number(route.params.accountID)]?.note ?? '';
    89          let editedNote = '';
    90          if (privateNote.trim() !== originalNote.trim()) {
    91              editedNote = ReportActions.handleUserDeletedLinksInHtml(privateNote.trim(), Parser.htmlToMarkdown(originalNote).trim());
    92              ReportActions.updatePrivateNotes(report.reportID, Number(route.params.accountID), editedNote);
    93          }
    94
    95          // We want to delete saved private note draft after saving the note
    96          debouncedSavePrivateNote('');
    97
    98          Keyboard.dismiss();
    99          if (!Object.values<Note>({...report.privateNotes, [route.params.accountID]: {note: editedNote}}).some((item) => item.note)) {
   100              ReportUtils.navigateToDetailsPage(report, backTo);
   101          } else {
   102              Navigation.goBack(ROUTES.PRIVATE_NOTES_LIST.getRoute(report.reportID, backTo));
   103          }
   104      };
   105
   106      return (
   107          <ScreenWrapper
   108              shouldEnableMaxHeight
   109              includeSafeAreaPaddingBottom={false}
   110              testID={PrivateNotesEditPage.displayName}
   111          >
   112              <HeaderWithBackButton
   113                  title={translate('privateNotes.title')}
   114                  onBackButtonPress={() => ReportUtils.goBackFromPrivateNotes(report, accountID, backTo)}
   115                  shouldShowBackButton
   116                  onCloseButtonPress={() => Navigation.dismissModal()}
   117              />
   118              <FormProvider
   119                  formID={ONYXKEYS.FORMS.PRIVATE_NOTES_FORM}
   120                  onSubmit={savePrivateNote}
   121                  style={[styles.flexGrow1, styles.ph5]}
   122                  submitButtonText={translate('common.save')}
   123                  enabledWhenOffline
   124              >
   125                  <Text style={[styles.mb5]}>
   126                      {translate(
   127                          Str.extractEmailDomain(personalDetailsList?.[route.params.accountID]?.login ?? '') === CONST.EMAIL.GUIDES_DOMAIN
   128                              ? 'privateNotes.sharedNoteMessage'
   129                              : 'privateNotes.personalNoteMessage',
   130                      )}
   131                  </Text>
   132                  <OfflineWithFeedback
   133                      errors={{
   134                          ...(report?.privateNotes?.[Number(route.params.accountID)]?.errors ?? ''),
   135                      }}
   136                      onClose={() => ReportActions.clearPrivateNotesError(report.reportID, Number(route.params.accountID))}
   137                      style={[styles.mb3]}
   138                  >
   139                      <InputWrapper
   140                          InputComponent={TextInput}
   141                          role={CONST.ROLE.PRESENTATION}
   142                          inputID={INPUT_IDS.PRIVATE_NOTES}
   143                          label={translate('privateNotes.composerLabel')}
   144                          accessibilityLabel={translate('privateNotes.title')}
   145                          autoCompleteType="off"
   146                          maxLength={CONST.MAX_COMMENT_LENGTH}
   147                          autoCorrect={false}
   148                          autoGrowHeight
   149                          maxAutoGrowHeight={variables.textInputAutoGrowMaxHeight}
   150                          defaultValue={privateNote}
   151                          value={privateNote}
   152                          onChangeText={(text: string) => {
   153                              debouncedSavePrivateNote(text);
   154                              setPrivateNote(text);
   155                          }}
   156                          ref={(el: AnimatedTextInputRef) => {
   157                              if (!el) {
   158                                  return;
   159                              }
   160                              if (!privateNotesInput.current) {
   161                                  updateMultilineInputRange(el);
   162                              }
   163                              privateNotesInput.current = el;
   164                          }}
   165                          isMarkdownEnabled
   166                      />
   167                  </OfflineWithFeedback>
   168              </FormProvider>
   169          </ScreenWrapper>
   170      );
   171  }
   172
   173  PrivateNotesEditPage.displayName = 'PrivateNotesEditPage';
   174
   175  export default withReportAndPrivateNotesOrNotFound('privateNotes.title')(PrivateNotesEditPage);
